insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 1, 'Ranked by increasing intervention, which sequence lists the five completion options the module sets out?', '["Frac pack, gravel pack, premium screen, wire-wrap screen, natural completion.", "Natural completion, standalone wire-wrap screen, standalone premium screen, gravel pack, then frac pack.", "Natural completion, standalone premium screen, standalone wire-wrap screen, frac pack, then a conventional gravel pack.", "Wire-wrap screen, natural completion, gravel pack, premium screen, then a frac pack evaluation."]'::jsonb, 1, 'A gravel pack sits above both standalone screens because sized gravel has to be placed in the annulus as well as a screen run.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 2, 'Which pair of questions does a completion type decision come down to, and how do they map onto the sieve?', '["Whether the sand is strong, and whether the well will make water.", "Whether the reservoir can carry the drawdown, taken from the uniformity, and whether the perforations will erode, taken from the fines.", "Whether a filter can be sized at all, from the uniformity, and whether it stays open, from the fines.", "Whether the screen can be run economically, and whether the gravel will pack out evenly."]'::jsonb, 2, 'Sizing works when coarse grains bridge the openings, and the bridge stays open only when little fine material can travel through it.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 3, 'Placing a gravel pack is said to decouple two size problems. What exactly does that decoupling mean?', '["Gravel is sized against the formation, and the screen then only has to be sized against that gravel.", "The screen is sized against the formation and the gravel holds it.", "Both the gravel and the screen are sized against the formation sand, so the two sizing calculations reinforce one another.", "Fines are removed by the gravel, so uniformity no longer enters the sizing at all."]'::jsonb, 0, 'The second sizing is the easy one because a commercial gravel is far more uniform than any formation sand.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 4, 'Under the ladder, what combination of the two numbers points to a standalone wire-wrap screen?', '["Uniformity below five together with fines below five percent.", "Uniformity below three with fines below ten percent, since a slot bridges coarse sand however much fine material is present.", "Uniformity below two together with fines below three percent, reversing the two limits.", "Uniformity below three together with fines below two percent, the tightest pair of thresholds."]'::jsonb, 3, 'That first rung is the least intervention on the ladder, so any sand satisfying it is not sent further down.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 5, 'Moving from a wire-wrap to a premium screen relaxes both thresholds. What physically allows that?', '["A premium screen has a much larger open area than a slotted tube.", "A woven multi-layer mesh offers many flow paths, so a bridge failing at one pore is caught at the next.", "The premium screen is run with sized gravel behind it, which filters the sand before it ever reaches the mesh surface.", "The single slot width of a wire-wrap screen is machined to a tighter tolerance than a mesh."]'::jsonb, 1, 'The uniformity limit moves from three to five and the fines limit from two percent to five percent.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 6, 'Why must the four rules be evaluated in order rather than treated as an unordered list?', '["Because the last rule would otherwise never be reached at all.", "Because each rule reads a different pair of sieve numbers, and only the ordering stops uniformity and fines being compared twice.", "The rules overlap, so taking the first match returns the least intervention that will actually work.", "Because a very clean sand would otherwise be sent straight to a frac pack evaluation."]'::jsonb, 2, 'A sand at a uniformity of two with one percent fines satisfies the first three rules, and ordering is what picks the wire-wrap screen.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 7, 'What property of the last two rules guarantees that the ladder always returns an indication?', '["The fourth rule is the exact logical complement of the third, so a sand failing one must satisfy the other.", "The last rule has no thresholds, so everything falls into it.", "The four rules together cover every uniformity value between one and six, which is the full range a sieve analysis returns.", "The thresholds are round numbers, so no sand can land exactly on a boundary."]'::jsonb, 0, 'The third rung reads uniformity below five and fines below ten percent, and the fourth reads at or above five or at or above ten.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 8, 'Between the third rung and the fourth, what changes in terms of what the fines are doing?', '["Above ten percent fines the screen slot erodes rather than plugs.", "Below ten percent fines the uniformity still governs, and above it the fines are simply produced to surface and handled there.", "The fourth rung is reserved for sands whose uniformity cannot be measured reliably.", "Below ten percent fines a conventional pack generally holds, and above that the pack itself will plug."]'::jsonb, 3, 'Above that limit the answer is a fines-tolerant design or a fracture that bypasses the near-wellbore region entirely.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 9, 'Five sieve curves were run through the ladder. What did the two sands in the middle of the set show?', '["Both sands landed on the same rung despite very different fines.", "Uniformities of about three point four and three point six gave different rungs because their fines differed.", "Their uniformities differed by more than a full point, which sent one to a premium screen and the other to a gravel pack.", "The sand carrying more fines received the premium screen and the cleaner one a gravel pack."]'::jsonb, 1, 'Four percent fines gave a premium screen and seven percent a gravel pack, while a fifth of a point of uniformity is inside sieve scatter.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 10, 'For those two sands, why did the uniformity have nothing left to decide?', '["Uniformity is not read at all by the second and third rules.", "Uniformity had been measured with too much scatter, so the ladder discards it whenever fines exceed two percent.", "Both sat comfortably between the uniformity thresholds of three and five, so neither was near a boundary.", "Their uniformities were identical to two decimal places, leaving only the fines free to differ."]'::jsonb, 2, 'The fines thresholds of two, five and ten put both sands close to the five, which is the number the rule was actually reading.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 11, 'Which weakness of a two-number indication would better sieve work genuinely fix?', '["A sample that is not the formation, where fines washed out during coring or the sand was caught at surface.", "The clay mineralogy, for which the ladder has no input.", "A bimodal grain size distribution, because two summary numbers will describe it correctly once enough sieve points are taken.", "The absence of a drawdown limit in the ladder, which no laboratory sieve programme can supply."]'::jsonb, 0, 'Bimodality and clay mineralogy stay invisible to two summary numbers no matter how careful the sieve programme becomes.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 12, 'At which part of the range does uniformity take back control of the indication?', '["In the middle band, where most real formation sands sit.", "Only where fines fall below two percent, because the first rung is the one rule that reads uniformity at all.", "Wherever the fines land exactly on one of the thresholds of two, five or ten percent.", "At the extremes, where the cleanest sand clears every threshold and the poorest fails on uniformity alone."]'::jsonb, 3, 'In that set the cleanest curve had a uniformity near one and a half and the poorest near six.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 13, 'Given that behaviour, where should a sand control laboratory programme spend its measurement effort?', '["On adding extra sieves at the coarse end of the stack.", "On the fines number, which both decides the middle rungs and is the hardest of the two to measure well.", "On repeating the uniformity determination several times, since a fifth of a point of scatter can move the indication.", "On the clay mineralogy, which the ladder reads alongside the two sieve numbers."]'::jsonb, 1, 'Fines can be lost during coring, and a stack that stops at a hundred microns simply never sees the material that matters.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 14, 'Rather than the ladder, what actually governs a sand control selection?', '["A larger sieve analysis with more points at the fine end.", "A correlation between uniformity and retained permeability, calibrated against wells already completed in the same field.", "Laboratory sand retention testing on the real sand, screen and fluid, with retained permeability measured.", "The operator''s field experience with completions in nearby analogue reservoirs."]'::jsonb, 2, 'That test costs weeks and real money, which is precisely why a cheap screening rule is worth having at all.'),
  ('perfsand', 'advanced', 'module', 'm01-choosing-a-completion-type', 15, 'Why does the engine attach a provenance string to the returned value instead of to the documentation?', '["A value copied into a table and then into a report loses its status unless the status travels with it.", "Because the documentation is not versioned with the engine code.", "Because the string names the four thresholds, and without them the ladder could never be recomputed later on.", "Because a user has to acknowledge the provenance before any indication is issued."]'::jsonb, 0, 'The string also names what governs instead, so a reader meets the retention test at the same moment as the indication.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 1, 'In one line, what does the Saucier rule specify for gravel sizing?', '["The gravel median is set at about twice the formation median.", "The median gravel grain is sized at five to six times the median grain size of the formation sand.", "The median gravel grain is sized at five to six times the coarse decile of the formation, measured on a sieve certificate.", "The gravel coarse decile is sized at five to six times the formation median grain."]'::jsonb, 1, 'Saucier''s 1974 flow experiments through packs of differing size established the band, and it needs only one input, the formation D50.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 2, 'Which failure does the lower end of the band, below about five times, guard against?', '["Formation grains bridging on the screen instead of the pack.", "Formation grains entering the pack pore throats and either travelling through the pack or lodging inside it and plugging it.", "A pack whose own pore throats are so small that its permeability adds a meaningful skin to the drawdown.", "Premature bridging of the carrier slurry before the annulus has been filled."]'::jsonb, 2, 'Extra drawdown spent on the pack feeds straight back into the sanding calculation as a worse case.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 3, 'Above roughly six times, a pack can plug from the inside. Why is that outcome worse than producing sand?', '["Plugging is not recoverable and it raises the drawdown, while sand production at least leaves the pack open.", "Plugging voids the sieve certificate supplied by the vendor.", "Plugging happens only in poorly sorted formations, so it signals that the sand control method itself was chosen wrongly.", "Plugged packs move the failure downstream to the surface separators and flowlines."]'::jsonb, 0, 'Both outcomes defeat a sand control completion, but only one of them can be produced back out of the well.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 4, 'Why is the criterion expressed as a ratio rather than an absolute grain size in microns?', '["Because sieve openings are reported in mesh rather than microns.", "Because vendors publish their catalogue rows as dual mesh designations, so an absolute size in microns could never be matched.", "Because the formation median is itself uncertain, so a ratio absorbs the measurement error.", "Bridging is scale free, since a grain bridges only when it is a large enough fraction of the pore throat."]'::jsonb, 3, 'Pore throat size scales with gravel size, so a single ratio serves a fine sand and a coarse sand alike.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 5, 'Gravel is sized on the formation median while a standalone slot is sized on the coarse decile. What separates the two?', '["The median is easier to read off a sieve analysis than a decile.", "Standalone screens are run in cleaner sands, so the coarse decile is the only percentile a vendor will certify for them.", "A pack must retain the bulk of the formation, whereas a single slot opening is bridged by the coarse grains.", "Saucier measured medians because his apparatus could not resolve the coarse tail."]'::jsonb, 2, 'Sizing gravel on D10 would give a much coarser pack that the formation median would walk straight through.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 6, 'Compare the width of the Saucier specification against the width of a commercial dual mesh cut.', '["The band spans a factor of about one point two, while a dual mesh designation spans a factor close to two.", "The two spans are roughly equal, at about a factor of two each.", "The band spans a factor of about two, which is wider than a dual mesh cut, and that is why several rows can match one sand.", "The band spans about one point five and a commercial cut spans about one point three."]'::jsonb, 0, 'The specification is therefore narrower than the product, which is the root of the whole matching problem.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 7, 'How does the engine assign a median to a catalogue row, and why is the result flagged approximate?', '["It takes the finer of the two sieve openings in the designation.", "It averages the medians of every row in the catalogue and scales that by the ratio of the row designations, which is only a proxy.", "It uses the coarser sieve opening, which overstates the row and is corrected later.", "It takes the mid range of the two sieve openings, whereas a vendor certificate gives the real distribution."]'::jsonb, 3, 'Naming the convention and flagging it keeps a reasonable shortcut from being read as a measured value.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 8, 'With no catalogue row inside the band, what does the engine hand back to the reader?', '["A refusal to size, since no defensible pack can be specified.", "An empty match list, a flag saying that it is empty, and the nearest row by median returned regardless.", "The nearest row on its own, presented as the design so that the workflow downstream is never interrupted by a gap.", "A widened band at four to seven times, recomputed until at least one row falls inside."]'::jsonb, 1, 'That combination tells the reader whether they sit inside the published rule or are exercising judgement.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 9, 'Sweeping seven representative formation medians from sixty to three hundred microns, how many find no commercial match?', '["Just one fails to match, the coarsest sand at three hundred microns.", "Five of the seven fail to match, which is why the catalogue is usually supplemented by a custom sieved cut on most jobs.", "Three of them fail to match, namely the sands at one hundred, two hundred and three hundred microns.", "Three fail to match, all of them at the fine end of the range below one hundred microns."]'::jsonb, 2, 'So a formation has less than an even chance of a clean match, worth knowing before a workflow assumes one.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 10, 'What creates the gaps into which a formation median can fall between catalogue rows?', '["Adjacent row medians step by roughly one point three to one point six, which is wider than the band itself.", "The catalogue simply stops short at the coarse end of the range.", "Vendors deliberately leave gaps so that custom sieved cuts remain a commercial product with a price and a lead time.", "Rounding the sieve openings to whole microns loses the rows that would otherwise fit."]'::jsonb, 0, 'Because every adjacent pair steps wider than the band, a gap sits between every pair of rows in the catalogue.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 11, 'Name the three responses open to a designer once the band comes back empty.', '["Widen the band, resample the sand, or run standalone screens.", "Take the nearest row, average the two adjacent rows into a blended pack, or perforate underbalanced to reduce the sand load.", "Order a custom cut, blend two catalogue rows, or accept a higher drawdown on the well.", "Take the nearest row, order a custom sieved cut, or reconsider the completion type, such as a frac pack."]'::jsonb, 3, 'Each response needs information a sieve analysis cannot hold, such as price, lead time and what is already on the boat.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 12, 'If the nearest row must be accepted, which direction of miss is the conservative one?', '["Going coarser, because a coarser pack always flows rather better.", "Going finer than five times, because the penalty there is pack resistance rather than formation invasion.", "Neither direction is safer, since both ends of the band were fixed by the same experiment and carry the same penalty.", "Going coarser than six times, because the pack keeps its own permeability intact."]'::jsonb, 1, 'A pack that adds skin can be lived with and quantified, while formation entering a pack can plug it beyond recovery.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 13, 'Precisely which catalogue row does the engine call the nearest sand?', '["The row whose median lies closest to the midpoint of the band, at five and a half times the formation.", "The row whose median lies closest to five times the formation.", "The row whose median lies closest to the upper edge of the band, since a slightly coarse pack is the safer place to sit.", "The row with the smallest ratio between its own designation width and the width of the band."]'::jsonb, 0, 'It is not the distance to five times, nor to six times, nor to the band taken as an interval.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 14, 'Distance to the band midpoint and distance to the band as an interval rank rows identically. Why?', '["Because the catalogue rows happen to be spaced evenly on a log scale.", "Because the band is so narrow that its midpoint and its two edges fall within the measurement error of any sieve analysis.", "Because rows inside the band are excluded from the ranking before the comparison is run.", "For any row outside the band the two distances differ by half the band width, a constant for every row."]'::jsonb, 3, 'Subtracting the same constant from every distance cannot change which of them comes out smallest.'),
  ('perfsand', 'advanced', 'module', 'm02-gravel', 15, 'What does the five to six band quietly assume about the formation being packed?', '["That the sand has already been screened for its clay content.", "That its uniformity is moderate, since a uniform sand tolerates coarser gravel and a poorly sorted one does not.", "That the formation has been characterised on at least three separate sieve analyses taken across the whole interval to be packed.", "That the sand is poorly sorted, which is the reason the band sits well above unity."]'::jsonb, 1, 'That assumption is what makes Saucier and the sand control ladder less independent than they first appear.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 1, 'In a gravel pack, what must the screen opening be smaller than?', '["Half of the gravel median diameter, taken as a safety fraction.", "The smallest grain in the gravel pack, because the screen there is a retainer and nothing more.", "The formation D10, since the sand grains rather than the gravel grains are what has to bridge across the slot.", "The gravel median grain size, which the dual sieve designation of the cut brackets from both sides at once."]'::jsonb, 1, 'The lower sieve of the dual designation is where that smallest grain comes from, so a twenty forty cut is nominally no finer than forty mesh.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 2, 'What becomes of a pack whose screen gauge is too coarse for the gravel?', '["It plugs, because the fines can no longer escape the pack.", "It bridges more tightly than intended, because the coarse grains left behind arch across the wider slots and choke the flow area.", "It loses its finest fraction through the slots, so the pack coarsens in place as those grains leave.", "It erodes a good deal faster, since a wider slot raises the fluid velocity through the open area of the screen."]'::jsonb, 2, 'The fraction lost is exactly the one doing the tightest filtering of the formation sand.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 3, 'Why is the gravel-pack sizing problem so much easier than the standalone one?', '["A commercial gravel spans about a factor of two in size while a formation sand spans ten or more.", "The gravel rule has fewer catalogue rows to search through.", "Standalone sizing needs a laboratory sieve analysis of the formation, whereas the gravel bound is read straight from the catalogue.", "Screens for gravel packs are made in a much finer series of gauges."]'::jsonb, 0, 'The hard filtering job was moved off the screen and onto the gravel, which was itself chosen by a rule with a single input.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 4, 'Which set lists the standard wire-wrap slot widths in thousandths of an inch?', '["Five values only: six, ten, sixteen, twenty and twenty five.", "Every even value from six through to twenty six, giving eleven gauges evenly spaced across the whole of the range.", "Eight, twelve, sixteen, twenty, twenty four and twenty eight, six evenly spaced values.", "Six, eight, ten, twelve, sixteen, twenty and twenty five, seven values spanning about a factor of four."]'::jsonb, 3, 'The gaps in the real series widen towards the coarse end rather than staying even.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 5, 'Given an upper bound from the rule, how does the engine choose off that series?', '["It takes whichever gauge is nearest the bound, above or below.", "It interpolates between the two neighbouring gauges and specifies a custom slot width at the exact value of the bound.", "It takes the largest standard gauge lying strictly below the bound, never one equal to it.", "It takes the smallest gauge anywhere in the standard series that still sits below the bound it was handed."]'::jsonb, 2, 'Largest is preferred because a wider opening means more open area, less pressure drop and less erosion.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 6, 'Seven catalog gravels run through the rule produce how many distinct gauges?', '["Seven, because the map from gravel to gauge is one to one.", "Five, since the two coarsest gravels share the widest gauge and the two finest share eight.", "Three, because the middle of the series is never selected and the gravels collapse onto the two extreme gauges only.", "Six, with only the two coarsest gravels sharing a single gauge between them."]'::jsonb, 1, 'Saturation at the coarse end happens because no gauge above twenty five thousandths exists in the series.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 7, 'Why do two of the finer gravels both land on the eight thousandth gauge?', '["Their smallest grains are identical in the catalogue.", "Fine gravels are handled by a separate rule that caps the slot at the gravel median rather than at the smallest grain.", "The engine rounds every result below ten thousandths down to the finest gauge on offer.", "Nothing exists between eight and ten, so smallest grains either side of ten both drop to eight."]'::jsonb, 3, 'The gaps low in the series are proportionally the largest, which is what makes the fine end collapse.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 8, 'How is the margin defined once a gauge has been selected?', '["The smallest gravel grain less the chosen gauge, read in microns as fineness nobody asked for.", "The chosen gauge divided by the smallest gravel grain.", "The difference between the largest and the smallest gauge in the standard series, which sets how coarse any slot can be.", "The gap between the formation D10 and twice that same value, evaluated at the gauge that was picked."]'::jsonb, 0, 'Both the gauge and the bound are catalogue values, yet their difference is neither, so reporting it proves the whole chain was done.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 9, 'What does a large margin cost the completion?', '["Open area, since a finer slot passes the same rate through less area, raising velocity and erosion.", "Nothing, because conservatism in sizing is always free.", "Gravel volume, because a finer screen has to be packed against a thicker annulus to hold the same production rate.", "Bridging strength, because the formation can no longer arch across so narrow an opening."]'::jsonb, 0, 'The other end is no more comfortable, as a near zero margin against a nominal bound will pass part of the real sieve tail.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 10, 'For a standalone completion, where should the slot width fall?', '["Between the formation D50 and twice that same D50.", "Between the smallest gravel grain and the largest standard gauge, which is the bound the gravel-pack rule already sets.", "Between the formation D10 and twice that D10, with both ends returned rather than one value.", "Between D10 and D40, so that the middle of the distribution is excluded."]'::jsonb, 2, 'A slot far under the lower end will bridge and then plug, because the middle of the distribution can reach it too.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 11, 'What is the reason a standalone slot is sized on the coarse decile?', '["Because the coarse decile is the easiest percentile to measure.", "With no gravel present the formation must bridge itself, and only grains larger than the slot can arch.", "Because the coarse decile is where the sorting coefficient is evaluated, and the ladder screens candidate sands on that number.", "Because sizing the slot at the median would halve the pressure drop measured across the completed interval."]'::jsonb, 1, 'Sizing at the median lets half the sample straight through, leaving too little coarse material to build an arch with.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 12, 'Where does the factor of two at the upper end of the window come from?', '["It doubles D10 to allow for sieve measurement error.", "It comes from the dual sieve designation of gravel, whose upper and lower sieve openings always differ by a factor of two.", "It is the ratio of the coarse decile to the median in a typical well sorted sand.", "An arch of grains can span a gap of about two grain diameters, and not a great deal more."]'::jsonb, 3, 'The window only holds for sands the ladder has already cleared, since a poorly sorted sand gives a computable and wrong answer.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 13, 'Does a correctly sized screen stop the well producing fines?', '["Yes, that is precisely what the bridge is sized to do.", "Yes, provided the slot was sized on the formation coarse decile rather than the median, which is what the window is for.", "No, material fine enough to pass the bridge still passes, and it goes on eroding surface equipment.", "No, though the produced fines are all captured within the gravel annulus behind the slots."]'::jsonb, 2, 'A screen that stopped everything would plug immediately, so it protects the wellbore rather than the facility.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 14, 'Field screen failures are most often caused by what?', '["Erosion, concentrated wherever the flow is concentrated, rather than an error in the slot size.", "Sizing the slot against the wrong grain percentile.", "Chemical attack from acid jobs and inhibitor squeezes, which no grain size calculation could ever have prevented.", "Collapse of the weakened near-wellbore rock onto the outside of the screen, leaving no annulus at all."]'::jsonb, 0, 'A hot spot erodes first and the hole it opens then grows, which concentrates the flow there even further.'),
  ('perfsand', 'advanced', 'module', 'm03-screens', 15, 'If the rock will fail at the drawdown the well needs, what does a screen achieve?', '["It raises the critical drawdown that the rock can sustain.", "It catches the failed material, a valid strategy and a different one from keeping the rock intact.", "It restores the strength of the near-wellbore rock by loading it against the pack, so that the failure no longer occurs.", "It removes the need for any sanding calculation on the well at all."]'::jsonb, 1, 'Everything computed in this module is a size, and size is necessary without being sufficient.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 1, 'State the classical Kirsch result for the hoop stress at the edge of a circular hole in an elastic plate.', '["The average of the two far-field stresses, all round the hole.", "Three times the larger far-field stress minus the smaller one, at the wall point where it is largest.", "Three times the smaller far-field stress minus the larger one, because a hole concentrates whichever direction is weaker.", "Twice the larger far-field stress, with the smaller one dropping out at the wall."]'::jsonb, 1, 'The solution is over a century old and assumes an infinite elastic plate, which is part of why a calibration knob is needed later.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 2, 'Which cavity is this stress concentration applied to in a sanding onset calculation?', '["The casing, treated as a hole cut in the cement sheath.", "The screen base pipe, treated as a stiff inclusion in the sand pack.", "The perforation tunnel, treated as a cylindrical cavity with the two stresses normal to its axis.", "The wellbore wall, the very problem the Geomechanics course solves for borehole stability, scaled to the reservoir section."]'::jsonb, 2, 'The same mathematics serves both holes, but the tunnel is far smaller and points a different way, so the stress pair differs.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 3, 'How much effective hoop stress does each unit of drawdown cost, and why?', '["Two units, since the pore pressure subtracts in the hoop term and again through radial equilibrium.", "One unit, because pore pressure enters the stress once.", "Three units, matching the factor of three that sits on the larger far-field stress.", "Half a unit, because the drawdown is shared between the tunnel wall and the undisturbed rock some distance behind it."]'::jsonb, 0, 'That doubling is why sanding is far more sensitive to drawdown than to any other quantity in the problem.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 4, 'Give the expression the engine uses for the critical flowing pressure.', '["The reservoir pressure less the rock strength.", "Half the sum of the two far-field stresses, less the unconfined compressive strength.", "The larger far-field stress minus the smaller, minus the strength, with no multiplier on any of the three terms.", "Three times the larger far-field stress, minus the smaller, minus the strength, all divided by two."]'::jsonb, 3, 'It comes straight from setting the effective hoop stress equal to the strength and solving for the flowing pressure.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 5, 'A margin computed as reservoir pressure less the critical flowing pressure comes out negative. What does that mean?', '["The two far-field stresses have been entered the wrong way round.", "The rock is strong enough that no drawdown limit needs to be placed on the well.", "The cavity is already unstable at zero drawdown, so the rock makes sand as soon as the well flows.", "Sand appears only once the drawdown grows past the size of the margin, so the number is a usable operating limit."]'::jsonb, 2, 'Such an interval needs sand control rather than a drawdown ceiling, since no rate is low enough to keep the wall intact.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 6, 'Which inputs does the criterion actually require?', '["Two far-field stresses in the plane normal to the cavity, plus one strength value, and nothing more.", "Stress, strength, porosity and the friction angle.", "Two stresses, a strength and the flowing pressure measured at the gauge depth.", "Two stresses, a strength, a Poisson ratio and a Biot coefficient, since the effective stress needs both elastic terms."]'::jsonb, 0, 'Three numbers in and one out is what makes the arithmetic checkable by hand, at the cost of any confining pressure dependence.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 7, 'For a perforation in a cased vertical well, which stress pair enters the criterion?', '["The two horizontal stresses, leaving the overburden out.", "The mean of the three principal stresses, paired with the reservoir pressure.", "The overburden with the minimum horizontal stress, because guns are always oriented along the maximum horizontal direction.", "The maximum and minimum of the overburden and the maximum horizontal stress, at the worst azimuth."]'::jsonb, 3, 'Taking the worst azimuth is deliberately conservative, since a real gun spreads tunnels over several azimuths and only some are worst.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 8, 'A standalone screen sits in a vertical open hole. Which stresses act in the plane normal to that cavity?', '["The overburden together with the pore pressure.", "The maximum and the minimum horizontal stress, and the overburden does not appear in the expression.", "The overburden and both horizontal stresses, because a vertical borehole wall is exposed to all three of them at once.", "The minimum horizontal stress paired with the flowing pressure at that depth."]'::jsonb, 1, 'On the published profile the tunnel margin is about half the open hole one, because the overburden usually dominates the triple term.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 9, 'Which geometry fits a gravel-packed cased hole?', '["The tunnel geometry, because the perforations remain the cavities even with gravel packed around them.", "The open hole geometry, since gravel replaces the rock.", "The open hole geometry, as the pack and screen act as one enlarged vertical cavity.", "Neither, because a gravel pack removes the free cavity wall and leaves the onset criterion nothing to be applied to."]'::jsonb, 0, 'The rule is simply to follow whichever cavity the sand would come from, which for any cased completion is the tunnel.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 10, 'What exactly is the strength boost factor, and what is its default value?', '["A safety factor on the drawdown, defaulting to zero.", "A correction on the flowing pressure that accounts for near-wall skin, defaulting to one.", "A multiplier on the far-field stresses that raises them to reservoir conditions, defaulting to the overburden gradient.", "A multiplier applied to the unconfined compressive strength in the criterion, and it defaults to one."]'::jsonb, 3, 'The engine does nothing with it except multiply, reports it back, and labels the result screening grade whatever value is used.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 11, 'Which laboratory test calibrates that multiplier for a particular rock?', '["A routine triaxial test at reservoir confining pressure.", "Thick-walled cylinder testing, with the observed failure stress compared to the unconfined strength.", "A sieve analysis of produced sand, whose uniformity coefficient scales the strength of the arch at the cavity wall.", "A sonic log calibrated against core, read at the depth of interest."]'::jsonb, 1, 'The test works because a cored central hole reproduces the cavity geometry directly, and reported values sit above one over a wide range.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 12, 'How does the margin respond to a change in the boost factor, and what better question does that invite?', '["It moves as the square of the boost, so small changes matter.", "It moves linearly, so the boost has to be argued to a decimal place first.", "It moves linearly, so ask which boost drives the margin to zero and compare that with published values.", "It is unaffected, because the boost scales the stresses and the strength together and the two effects cancel out."]'::jsonb, 2, 'Linearity holds because the boost only scales the strength, and the strength enters the expression exactly once.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 13, 'Which question does this onset result leave unanswered?', '["Whether the wall reaches its strength at a given pressure.", "Which of the two cavity geometries a given completion should use.", "The maximum drawdown available before onset, which needs a separate transient model of the near-wellbore region.", "How much sand a failed cavity makes, over what timescale, and whether the well is therefore uneconomic."]'::jsonb, 3, 'A wall at its failure stress degrades rather than collapsing at once, and plenty of wells produce economically while making sand.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 14, 'Why does the workflow stop at onset instead of predicting a sand rate?', '["Because sand rate is measured at surface anyway.", "Onset has a closed form from three stresses and a strength, while a rate needs three empirical models.", "Because a rate calculation would need the grain size curve, and sieve data are rarely available at every depth in the interval.", "Because onset is conservative and a rate would understate the risk to the completion."]'::jsonb, 1, 'The three a rate would need are a failure mechanics model, an erosion model and a transport model, none of them well constrained.'),
  ('perfsand', 'advanced', 'module', 'm04-sanding-onset', 15, 'Name the three uses of the sanding margin and say which one an interval sweep supports.', '["Setting a drawdown limit, deciding whether sand control is needed, and comparing depths, which the sweep serves.", "Rate allocation, choke sizing and gravel sizing, all served by the sweep.", "Screen selection, workover timing and rate allocation, with the sweep serving rate allocation.", "Screen selection, gravel sizing and pump sizing, and the sweep supports gravel sizing because it reports a size at every depth."]'::jsonb, 0, 'Comparison along depth matters most because a completion decision usually turns on whether the weak zone is thin or tens of metres thick.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 1, 'What does each row produced by the sanding sweep carry?', '["The measured depth and the critical flowing pressure only.", "The measured depth, the true vertical depth, the pore pressure, the critical flowing pressure and the margin.", "The true vertical depth, the full stress tensor, the rock strength inputs and the sand production rate predicted at that station.", "The station depth, the applied drawdown and the perforation density chosen there."]'::jsonb, 1, 'The margin is the gap between the critical flowing pressure and the pore pressure, and it is the column the governing row minimises.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 2, 'Which conversion inside the sweep deliberately avoids linear interpolation?', '["The pore pressure lookup on the supplied depth grid.", "The stress and strength curves from the Geomechanics course, which are resampled onto a cubic spline before any station is evaluated.", "The measured depth to true vertical depth conversion, which uses the exact minimum curvature increment.", "The margin, which is recomputed from the two pressures rather than read off a curve."]'::jsonb, 2, 'Linear interpolation along an arc misses by decimetres at these depths, and a decimetre of true vertical depth is real stress.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 3, 'Define the governing row of an interval sweep.', '["The station carrying the smallest margin, because a completion is limited by its weakest single point.", "The deepest station in the perforated interval.", "The station where the critical flowing pressure is highest, since that is the one that constrains the drawdown the operator can apply.", "The average of the station margins across the whole perforated interval."]'::jsonb, 0, 'The engine returns it alongside the rows, so a caller who wants a single number gets the right one without reading the profile.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 4, 'Beyond the governing row itself, what extra information does a full profile give?', '["The absolute value of the worst margin in the interval.", "The direction in which the margin trends with depth, which is the only thing that decides whether sand control is needed at all.", "Whether the survey stations used for the conversion were spaced closely enough.", "How much of the interval sits near the limit, which separates a thin weak streak from a broadly weak zone."]'::jsonb, 3, 'One interval might be perforated selectively to dodge the streak, while an interval with half its rows negative needs sand control instead.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 5, 'In the Suite application, what does the guard on the Sanding tab drive and check?', '["It rejects any step that fails to divide the interval.", "It pushes the tab''s step through seven values and checks each sweep starts at the top and ends at the base.", "It reruns the golden fixture inside the browser whenever the tab is opened, so the user sees a warning banner if the rows disagree.", "It hides the step field unless the interval length is a round number."]'::jsonb, 1, 'The engine tests use nine step sizes while the application guard uses seven, so the endpoint rule is checked on both sides of the boundary.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 6, 'State the original defect in the stepping loop.', '["It walked in whole steps while the depth was at or above the bottom, so a ragged last step was dropped.", "It stepped upwards from the bottom instead of downwards.", "It evaluated every station twice whenever the step failed to divide the interval, so the governing row was reported from a duplicate.", "It clamped the last station to the interval top rather than to its bottom."]'::jsonb, 0, 'Only steps that divide the interval evenly escaped it, because there the last whole step lands exactly on the bottom.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 7, 'For an interval from 2450 to 2550 metres at a thirty metre step, which rows did the broken sweep return?', '["Rows at 2450, 2480, 2510, 2540 and 2550 metres.", "Rows at 2450, 2480, 2510 and 2550 metres, because the final station was clamped forward onto the interval bottom as intended.", "Rows at 2450, 2480, 2510 and 2540 metres, which leaves the deepest ten metres of the interval unscreened.", "Rows at 2480, 2510 and 2540 metres, the top station having been skipped."]'::jsonb, 2, 'Nothing in the output announced the early stop, so a missing row had to be spotted by reading the last depth.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 8, 'Why could the clamp and the break written to prevent this never execute?', '["They sat after an unconditional return statement.", "They were guarded by a validation on the step size that rejected any value which failed to divide the interval into whole stations.", "They were written for a different sweep and never wired into this one.", "The while condition exited the loop first, so both lines were dead except when the step divided evenly."]'::jsonb, 3, 'In the evenly dividing case the pair did run, but there they were unnecessary, so they added nothing anywhere.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 9, 'On the weakened profile, how did truncation distort the reported governing margin?', '["It read about plus zero point six five megapascals instead of the true minus one point two five at the base.", "It was reported roughly two megapascals too low.", "It was reported at the right station but with pore pressure taken from the station above, which shifted the value by about one megapascal.", "It stayed negative but shrank to roughly a tenth of its true magnitude at the base."]'::jsonb, 0, 'The sign flips, so the screening claims drawdown is available on an interval whose base fails at any drawdown at all.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 10, 'Give the one line check a reader can apply to any interval sweep output.', '["Confirm the row count equals the interval length over the step.", "Confirm the last row sits exactly at the interval bottom, whatever step size was typed into the tool.", "Confirm the margins change smoothly between rows, since a jump shows that a station was interpolated from the wrong survey bracket.", "Confirm the leading row sits exactly at the top of the perforated interval."]'::jsonb, 1, 'The start is nearly always right because it is the initial value, so the end is where an off by one error hides.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 11, 'Which property of the golden fixture stopped it detecting the missing station?', '["It stored too few significant digits for the comparison.", "It was recorded from the engine itself rather than from an independent source, so it agreed with whatever the engine happened to produce.", "It used a deviated well, so the depth conversion masked the absent station.", "It swept a hundred metre interval at a ten metre step, and that divides evenly, so the ragged case never arose."]'::jsonb, 3, 'At a dividing step an endpoint inclusive sweep and one that stops at the last whole step give identical rows, so no number of digits could separate them.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 12, 'Why did the supposedly independent oracle fail to be independent?', '["It was written in the same language as the engine.", "It read the engine''s own output as a starting point and recomputed only the margin column, so the station list was never derived again.", "Its loop transcribed the engine''s, with the same while condition, the same clamp and the same break.", "It shared the interpolation helpers the engine uses for the stress curves."]'::jsonb, 2, 'Independence means deriving the answer by a different route, not typing the same control flow again somewhere else.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 13, 'How does the rebuilt oracle now establish genuine independence?', '["It compares its rows against a second golden file.", "It builds the list of depths to visit explicitly and self asserts the endpoint rule at nine step sizes.", "It recomputes the critical flowing pressure from first principles using a failure criterion different from the one the engine applies.", "It runs the same loop but in a language with stricter bounds checking."]'::jsonb, 1, 'A list of stations and a while loop are different enough that a mistake in one is unlikely to be a mistake in the other.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 14, 'Set this defect beside the reduction defect found in the previous course.', '["That was a wrong selection over correct rows, whereas here every row was right and one was missing.", "Both were arithmetic errors inside a single row.", "That one was caught by an oracle working correctly, whereas this one surfaced only after a user reported a suspicious field result.", "Both were caused by floating point comparison on the station depths."]'::jsonb, 0, 'Both survived because the comparison compared the wrong thing, one never comparing the summary and the other matching a wrong set.'),
  ('perfsand', 'advanced', 'module', 'm05-the-sweep-and-the-missing-row', 15, 'Of the two new engine tests, which one would fail loudly on a regression?', '["The nine step size test, because it runs many more cases.", "The nine step size test, because it checks that stations increase strictly and that none of them is placed past the interval bottom.", "The weakened profile test, since it asserts a sign on the governing margin rather than checking the mechanism.", "The application guard, because it drives the tab parameter through seven values."]'::jsonb, 2, 'It runs the weakened profile at a dividing step and a non dividing one and requires both to place a negative governing margin at the base.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 1, 'A candidate submits a capstone sanding sheet whose rows were built from the overburden and the maximum horizontal stress, although the brief specifies an open hole cavity. What has that done to her results?', '["Nothing, because the two geometries share a stress pair.", "The perforation tunnel pair was used, so the overburden displaced the minimum horizontal stress in every row.", "Only the governing row is affected, since the choice of cavity geometry changes the depth at which the smallest margin is found.", "Her critical pressures are too low, but the margins she reported remain correct."]'::jsonb, 1, 'Three times the larger stress dominates the expression, so bringing the overburden in raises the critical pressure and the open hole case is the looser of the two.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 2, 'A trainee''s capstone sweep ends at a station one whole step above the base of the interval, and he insists the step he typed was a sensible round number. What do you tell him?', '["A round step is exactly what a well posed sweep requires.", "He should reduce the boost factor until the final station lands on the base, which is the usual way of curing a ragged interval.", "His sweep truncated, because the step set for this capstone does not divide the interval evenly.", "The last station on a sweep is always one whole step short by design, so his output needs no correction."]'::jsonb, 2, 'The clamp and the break in the routine were written for precisely this ragged last step, and a sweep whose final row is not the interval base is wrong whatever step was typed.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 3, 'A submission reports a margin at the interval base that is smaller than the governing margin it also quotes. Before looking at any arithmetic, what can you conclude?', '["One of the two must be wrong, since the governing margin is the smallest margin anywhere on the sweep.", "Both can stand, as they are measured at different depths.", "It shows the profile weakens downwards, which is the expected behaviour whenever a multiplier above one is applied.", "It proves the candidate used the perforation tunnel geometry at the bottom row only."]'::jsonb, 0, 'This check costs nothing and it catches a mislabelled row long before any stress arithmetic needs to be examined.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 4, 'A reviewer notices a sheet claiming a positive governing margin at the stated boost, while the boost at zero margin it reports sits above that stated boost. Is the pair consistent?', '["Yes, since the two quantities are measured in different units.", "Yes, provided the bisection was run on the base row rather than the governing row, which reverses the ordering.", "No, because the margin falls as the boost rises, so both of the numbers he quotes must in fact be negative.", "No, because a positive margin at the stated boost forces the zero crossing to lie below that boost."]'::jsonb, 3, 'The margin is linear in the boost, so the crossing is a single point and the ordering check is exact rather than approximate.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 5, 'A colleague points out that the sanding margin is linear in the strength multiplier and proposes replacing the graded bisection with one secant step. How do you respond?', '["The margin is not linear in the multiplier, so a secant fails.", "He is right about the linearity and a secant would land in one step, but the lab grades a bisection.", "A secant cannot be used because the strength multiplier enters the hoop stress expression twice and the relation curves sharply.", "Either method is banned here, since the crossing must be read straight off the sweep table."]'::jsonb, 1, 'That linearity is what makes the zero crossing worth quoting at all, because it turns an argument about calibration into one comparable number.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 6, 'An assessor is asked why the gauge margin carries marks when both the slot gauge and the grain bound come from published tables. What is the defence?', '["The difference sits in neither table, so reporting it proves both selection steps were done correctly.", "It is graded simply because it is the quickest value to mark.", "The margin is graded because vendors publish it directly on the sieve certificate and it is therefore easy to verify.", "It is graded because the gauge series is continuous, so the margin between them can take any value at all."]'::jsonb, 0, 'It is also the one capstone value a real sieve certificate would move, since a nominal bound has a tail of finer material below it.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 7, 'A learner protests that the lower edge of the gravel band was already computed back in the Associate tier and should not be marked a second time. What justifies grading it again?', '["It is regraded because the capstone sand has changed.", "It is regraded because the Saucier multiplier used in the Expert tier differs from the one taught to Associates.", "Everything downstream in this tier depends on it, so an error there would propagate into the gauge margin.", "It is regraded because the interval and the boost factor are both new for this capstone exercise."]'::jsonb, 2, 'The capstone sand is deliberately the same one, so the value doubles as a check that the earlier chain still reproduces.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 8, 'A reviewer insists the deepest station must govern, because the base of a perforated interval is usually the weakest rock in it. What does the capstone profile actually show?', '["The deepest station governs, exactly as the reviewer expects.", "The margin rises with depth here, so the top station governs and the deepest one is the loosest.", "Neither end governs, because the smallest margin on a swept interval always falls at the midpoint of the perforated section.", "The two ends tie, because a boost factor above one removes any trend of margin with depth."]'::jsonb, 1, 'The direction of that trend has to be read off the sweep rather than assumed, which is one reason both ends are reported.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Asked why the capstone awards marks for a margin at the base when that station is not the governing one, an engineer shrugs. Give him the reason.', '["It is graded because the base always carries the smallest margin.", "It is graded because a critical flowing pressure cannot be quoted without a matching value at the opposite end of the interval.", "It is graded because the reservoir pressure at the base is the only such pressure the brief actually states.", "That station exists only because the sweep runs to the base, so it proves the truncation defect is gone."]'::jsonb, 3, 'A candidate who reports it also has to say how many rows the sweep produced and at what depth the last of them sits.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 10, 'A capstone sheet has been worked with the strength multiplier left at its default of one, although the brief sets a different value. What is the consequence?', '["Every critical flowing pressure shifts, because the multiplier scales the strength in each row of the sweep.", "Only the boost at zero margin is affected by the omission.", "Nothing changes in the sweep, since the multiplier is reported alongside the result but never enters the failure criterion.", "The governing row moves to a new depth while every margin keeps the value already reported."]'::jsonb, 0, 'The shift at each station is proportional to the local strength, so a profile whose strength varies with depth is not simply displaced by a constant.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 11, 'At an interview you are asked what the Expert tier of this course equips you to do with a sieve analysis in hand. Which claim is defensible?', '["Predict the sand rate a failing perforation will produce.", "Derive the stress and strength profile from logs and then certify a completion design without any laboratory retention testing.", "Reach a completion type, size a gravel and both screen types, then sweep a critical drawdown down an interval.", "Rerun a perforation skin in its four components and rank a gun catalogue by the productivity ratio each row implies."]'::jsonb, 2, 'Each of those results also carries a status, and being able to say what a screening grade number is worth is part of the claim.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 12, 'A graduate who skipped the Geomechanics course asks whether that matters now this tier is finished. What would be missing on a real well?', '["The sieve convention used to read a formation curve.", "The stress and strength profile the sanding sweep consumes, which this course never derives for itself.", "The minimum curvature survey arithmetic that converts a measured depth into a true vertical depth at each station.", "The retained permeability measurement that a sand retention test reports."]'::jsonb, 1, 'The sweep interpolates that profile linearly in true vertical depth, so its resolution is inherited rather than computed here.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Before a drawdown limit is issued on a live well, a team wants to adopt a strength multiplier quoted in a published paper. What does the course advise instead?', '["Run a thick walled cylinder test, or find the multiplier at which the margin reaches zero and judge it.", "Adopt the paper value, since the range reported is narrow.", "Set the multiplier to one and accept the conservatism, because a calibrated value can never be defended to a regulator.", "Average several published values so that the answer does not rest upon the judgement of any single author."]'::jsonb, 0, 'If that zero crossing sits far below anything the literature reports, the interval is safe under any plausible calibration and the core test can wait.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 14, 'The pack has been ordered and the actual gravel is on the boat. Which recalculation does the course ask for before a screen gauge is signed off?', '["Recompute the formation median from that same certificate.", "Recompute the Saucier band using the shipped pack median, because the band is defined against the gravel rather than the sand.", "Recompute the grain bound from the real smallest grain on the sieve certificate rather than the nominal cut.", "Recompute the drawdown limit, since the pack alters the stress acting at the cavity wall."]'::jsonb, 2, 'A nominal cut has a tail below its lower sieve, so a margin that looked comfortable against the catalogue can be thin against the real pack.'),
  ('perfsand', 'advanced', 'module', 'm06-the-expert-reading', 15, 'You are handed an unrelated routine that walks a pressure range in steps and hands back a table. Which habit from this course applies first?', '["Check that the step size divides evenly into the range.", "Check that an independent oracle written in another language reproduces the same control flow before trusting it.", "Check the middle of the table first, because a reduction taken over its rows tends to fail near the centre.", "Check both ends of the table it gave you, since the start is nearly always right and the end is not."]'::jsonb, 3, 'The start is simply the initial value and rarely wrong, which is why an off by one lives at the far end of a walked range.'),
  ('perfsand', 'advanced', 'final', null, 1, 'A core report lands on your desk giving a uniformity coefficient of 2.6 and a fines content of 1.4 percent. Which rung does the ladder return, and on what reasoning?', '["A gravel pack, because gravel suits any uniformity below five.", "A premium standalone screen, because a woven mesh is always the safer buy whenever the fines sit comfortably under five percent.", "A standalone wire-wrap screen, since the first rule holds and the ladder stops at the least intervention.", "A frac pack evaluation, since 1.4 percent fines is enough to plug a slotted tube."]'::jsonb, 2, 'Later rules are satisfied here as well, which is precisely why the order matters rather than mere membership.'),
  ('perfsand', 'advanced', 'final', null, 2, 'Two wells in one field return sieve numbers of 3.4 uniformity with 4 percent fines, and 3.6 uniformity with 7 percent fines. What separates their indications?', '["The fines alone, since both uniformities sit inside the three to five range and neither is near a threshold.", "The uniformity, which crosses a threshold between the two.", "Neither number, because a difference of that size falls within the scatter of any routine sieve analysis and is noise.", "Both numbers together, each moving the answer by roughly the same amount."]'::jsonb, 0, 'A fifth of a point of uniformity lies inside laboratory scatter, whereas three points of fines does not.'),
  ('perfsand', 'advanced', 'final', null, 3, 'A sand control programme can afford one laboratory improvement: extra sieves at the coarse end, or a stack carried well below one hundred microns. Which buys more?', '["Extra coarse sieves, which sharpen the uniformity coefficient.", "Neither, because the ladder thresholds are round judgement numbers and no laboratory refinement can change what they return.", "Extra coarse sieves, because the coarse decile also sizes a standalone slot.", "The deeper stack, since most sands sit in the middle of the range where the fines are what the rule reads."]'::jsonb, 3, 'Fines are also the fraction most easily lost during coring, so the measurement is fragile as well as decisive.'),
  ('perfsand', 'advanced', 'final', null, 4, 'Retention testing on the real sand, screen and completion fluid says a premium screen holds, while the ladder had indicated a gravel pack. How is the conflict settled?', '["Split the difference by running a light gravel pack anyway.", "The laboratory result governs and the ladder is wrong for this sand, not evidence against the test.", "Rerun the sieve analysis until the two numbers move enough to agree with the retention test before ordering any hardware.", "Keep the ladder, since its thresholds come from published selection literature."]'::jsonb, 1, 'Narrowing five options to two so that the right candidates reach the flow loop is the whole of what a screening rule buys.'),
  ('perfsand', 'advanced', 'final', null, 5, 'A sieve curve is plainly bimodal, yet its summary numbers come out as uniformity 4.2 with 6 percent fines, so a gravel pack is indicated. What is the honest reading?', '["It is sound, since both inputs were measured correctly.", "It is sound provided the second mode lies above the coarse decile, where it can have no influence on bridging behaviour.", "The indication is unreliable here, because two summary statistics cannot see a bimodal shape at all.", "It is wrong, and the fourth rung should be substituted whenever a curve is bimodal."]'::jsonb, 2, 'Clay mineralogy falls in the same category, an input the rule has no field for and which changes how fines behave.'),
  ('perfsand', 'advanced', 'final', null, 6, 'An engineer argues that the ladder must have a hole in it, since some sand somewhere could fail every rule. Show why that cannot happen.', '["The fourth rule is the exact logical complement of the third, so anything failing the third satisfies it.", "A default of gravel pack is applied when no rule matches.", "The thresholds of two, three, five and ten were chosen to overlap so that every plausible sand meets at least one rule.", "The rules are evaluated in order, and ordering removes the possibility of a gap."]'::jsonb, 0, 'Exhaustiveness is worth having in any rule that gets applied to whatever a laboratory happens to send back.'),
  ('perfsand', 'advanced', 'final', null, 7, 'The only material available was caught at the surface separator during a clean-up flow. What does that do to an indication drawn from it?', '["Nothing, provided the sample mass is enough for a full stack.", "It improves it, because material that has already travelled through the completion is what a screen must actually stop.", "It biases the uniformity coefficient only, and leaves the fines content trustworthy.", "It undermines it, because such a sample is what the well was willing to give up rather than the formation."]'::jsonb, 3, 'A better sieve stack cannot repair this, since the defect lies in what was sampled and not in how it was measured.'),
  ('perfsand', 'advanced', 'final', null, 8, 'Your formation median comes back at 120 microns. Work out the Saucier band and say what its two edges are protecting.', '["Twenty four to thirty microns, the same ratio applied inversely.", "Six hundred to seven hundred and twenty microns, guarding pack permeability below and invasion above.", "One thousand two hundred to one thousand four hundred and forty microns, since the rule is applied to the coarse decile.", "Six hundred microns exactly, because the rule returns a single sizing target."]'::jsonb, 1, 'The ratio holds for a fine sand and a coarse one alike, since bridging depends on a fraction of the pore throat.'),
  ('perfsand', 'advanced', 'final', null, 9, 'Nothing in the catalogue lands inside the band, and the two neighbouring rows sit one either side of it. What does the engine hand over?', '["The nearest row only, presented as the sizing recommendation.", "A refusal, on the grounds that recommending a pack outside the published band would misstate what the rule supports.", "An empty match list, a flag recording that it is empty, and the nearest row by median regardless.", "A widened band, stretched until at least one commercial cut falls inside it."]'::jsonb, 2, 'Returning both keeps the reader aware of whether they sit inside the rule or are exercising judgement.'),
  ('perfsand', 'advanced', 'final', null, 10, 'Forced onto the nearest row, you can miss the band on the fine side or on the coarse side. Which way should you err, and for what reason?', '["Finer, because a slightly tight pack costs permeability while a coarse one lets formation grains in.", "Coarser, since open pore throats keep the pack conductive.", "Either way, because the band edges are empirical and a miss in one direction carries the same consequence as the other.", "Coarser, because a coarse pack can always be tightened by the screen behind it."]'::jsonb, 0, 'A plugged pack is not recoverable and it raises drawdown, which feeds straight back into the sanding calculation.'),
  ('perfsand', 'advanced', 'final', null, 11, 'A colleague ranks the catalogue by distance to whichever band edge is nearer, instead of by distance to the midpoint. What happens to the ranking?', '["It reverses, because the two edges lie on opposite sides.", "It changes only for rows inside the band, where the interval measure returns zero and the midpoint measure does not.", "It changes whenever more than one row lies outside the band on the same side.", "It is unchanged, since the two distances differ by half the band width for every row outside the band."]'::jsonb, 3, 'The argument leans on the band being symmetric about its midpoint in the metric used, worth checking before reuse.'),
  ('perfsand', 'advanced', 'final', null, 12, 'Someone sizes the gravel on the formation coarse decile rather than the median, reasoning that coarse grains do the bridging. Where does that go wrong?', '["Nowhere, since the coarse decile is the right Saucier input.", "It gives a far coarser pack that the formation median walks straight through, since the pack retains the bulk.", "It gives a much finer pack than the band allows, so the pack contributes its own skin and the well needs extra drawdown.", "It swaps the band edges, so the pack lands mid-range instead of at five and a half times."]'::jsonb, 1, 'That reasoning belongs to the standalone slot, where a single opening is bridged by the coarse grains directly.'),
  ('perfsand', 'advanced', 'final', null, 13, 'A pack has ended up finer than five times the formation median. Trace the consequence forward into the sanding calculation.', '["Nothing follows, since the two calculations share no inputs.", "Formation grains enter the pack and lodge in its throats, so it plugs from within and raises the drawdown further.", "The pack contributes its own skin, and the extra drawdown needed shows up as a worse case at the cavity wall.", "The gauge selection tightens, because a finer pack has a finer smallest grain."]'::jsonb, 2, 'A gravel pack is meant to be transparent to flow, so a pack with its own pressure drop has defeated its purpose.'),
  ('perfsand', 'advanced', 'final', null, 14, 'The ladder has returned the fourth rung on a badly sorted sand. Can the Saucier rule still be applied to it as written?', '["Not confidently, because the five to six band assumes a formation of moderate uniformity in the first place.", "Yes, because Saucier needs only the formation median as input.", "Yes, and the band should simply be widened to six or seven times the median to allow for the extra fine material.", "No, because the fourth rung rules out placing gravel of any size in the annulus."]'::jsonb, 0, 'The two rules of this tier are less independent than they look, since both rest quietly on how well sorted the sand is.'),
  ('perfsand', 'advanced', 'final', null, 15, 'The bound from the gravel-pack rule falls exactly on a listed standard gauge. Why does the engine step down to the gauge below it?', '["To leave room for erosion to widen the slot in service.", "Because the gauge series is quoted in thousandths of an inch and a metric bound can never coincide with a listed value.", "To keep the margin large, since a generous margin is the conservative choice on any job.", "The rule is a strict inequality, and an opening equal to the smallest grain would let that grain through."]'::jsonb, 3, 'Stepping down costs open area, which is why the selection takes the largest gauge that still clears the bound.'),
  ('perfsand', 'advanced', 'final', null, 16, 'Two of the coarsest catalogue gravels both come back on the twenty five thousandth gauge. What is that result telling you?', '["The two gravels must share the same nominal smallest grain.", "The series saturates at its coarse end, so both screens are finer than needed and give up open area.", "The rule has been applied to the pack median rather than the smallest grain, which collapses distinct gravels onto one gauge.", "The screens will erode faster than the rule intends, since the slot is wide."]'::jsonb, 1, 'Seven catalogue gravels map onto only five gauges, and the mapping is not one to one at either end of the series.'),
  ('perfsand', 'advanced', 'final', null, 17, 'One gravel''s smallest grain sits just above a standard gauge; another''s sits just below the next gauge up. Compare what each screen ends up paying.', '["Both pay the same, since the rule is applied identically.", "The first loses open area and the second risks the tail, because a bound just above a gauge forces the finer selection.", "The first gets a small margin and risks the real tail, the second a large one and loses flow area.", "Only the second pays anything, because a small margin carries no cost worth naming."]'::jsonb, 2, 'Neither position is comfortable, and computing the number is how you learn which end you are standing on.'),
  ('perfsand', 'advanced', 'final', null, 18, 'A standalone completion is indicated and the formation coarse decile measures 150 microns. What slot width does the Coberly window allow?', '["Between one hundred and fifty and three hundred microns, with both edges returned rather than one value.", "Seven hundred and fifty to nine hundred microns, by Saucier.", "Below one hundred and fifty microns, so that every grain in the coarse decile is arrested at the slot rather than passing.", "Three hundred microns exactly, since an arch can span twice the grain diameter."]'::jsonb, 0, 'A slot far under the decile will bridge and then plug, because the middle of the distribution can now reach it.'),
  ('perfsand', 'advanced', 'final', null, 19, 'The Coberly window has been computed for a sand that the ladder placed on the gravel pack rung. What is wrong with the resulting number?', '["Nothing, as the window depends only on the coarse decile.", "It is too wide, and halving both edges restores a slot that a poorly sorted formation can still bridge across reliably.", "It becomes unreliable only where the fines exceed ten percent of the whole sample.", "It computes cleanly and is still wrong, since the window assumes a sand the ladder has already cleared."]'::jsonb, 3, 'The window rests on the coarse decile representing a substantial fraction of the sample, and sorting decides that.'),
  ('perfsand', 'advanced', 'final', null, 20, 'Production reports fines eroding surface chokes on a well whose screen was correctly sized. Is the screen at fault?', '["Yes, the gauge must be one step too coarse for that pack.", "No, since material fine enough to pass the bridge is meant to pass, and the screen protects the wellbore.", "Yes, because a screen retaining the coarse and middle fractions should by the same mechanism retain the fine tail.", "No, because a screen that stopped the fines would show no pressure drop at all."]'::jsonb, 1, 'A filter that stopped everything would plug immediately, so passing the fines is a design choice and not a failure.'),
  ('perfsand', 'advanced', 'final', null, 21, 'You have sized a gauge with almost no margin against the nominal bound, and the pack is already on the boat. What is the exposure?', '["The screen will plug immediately, since the slot is too tight.", "There is no exposure, because a nominal designation is a guaranteed minimum and no grain below the lower sieve exists.", "The real cut carries a tail below its nominal lower sieve, and that tail will pass through the slots.", "Erosion, because a tight slot raises the velocity through what open area remains."]'::jsonb, 2, 'Asking for the certificate and recomputing the bound from the measured smallest grain is what makes a margin mean anything.'),
  ('perfsand', 'advanced', 'final', null, 22, 'Take a maximum far-field stress of 55 MPa, a minimum of 42 MPa and an unconfined strength of 30 MPa. What critical flowing pressure follows?', '["Forty six and a half megapascals, being three times the larger less the smaller less the strength, halved.", "Ninety three megapascals, taken with no halving applied at all.", "One hundred and twenty three megapascals, from three times the larger stress with the smaller and the strength added on.", "Sixty one and a half megapascals, with the strength added rather than subtracted."]'::jsonb, 0, 'The boost sits at its default of one here, and any other value would scale the strength term before that subtraction.'),
  ('perfsand', 'advanced', 'final', null, 23, 'A well is drawn down by one further megapascal at the perforations. What does that cost at the wall of the cavity?', '["One megapascal, moving in direct proportion with the drawdown.", "Three megapascals, because the Kirsch expression carries a factor of three on the larger of the two far-field stresses.", "Half a megapascal, because the rearranged criterion is divided through by two.", "Two megapascals of effective hoop stress, since the flowing pressure enters the expression twice over."]'::jsonb, 3, 'That doubling is why sanding responds far more sharply to drawdown than to anything else in the problem.'),
  ('perfsand', 'advanced', 'final', null, 24, 'A cased hole has been gravel packed, and the analyst enters the two horizontal stresses for the sanding check. What has gone wrong?', '["Nothing, because gravel packing makes the wellbore the cavity.", "The cavities are still the tunnels, so the pair should be the overburden and maximum horizontal stress.", "The strength should also have been raised, since a gravel pack confines the tunnel wall and makes the rock behave stronger.", "The two horizontal stresses should be swapped, taking the minimum as the larger."]'::jsonb, 1, 'Overburden is usually the largest stress in a normally stressed basin, so leaving it out flatters the margin considerably.'),
  ('perfsand', 'advanced', 'final', null, 25, 'Rather than argue over the right boost factor, you compute the multiplier at which the governing margin reaches zero. What does a very low answer tell you?', '["That the rock is weak and will start producing sand at once.", "That the criterion was run with the wrong stress pair, since a plausible boost should always exceed the reported range.", "That the interval is safe under any calibration the literature supports, so the core test can wait.", "That the calibration matters, and a thick-walled cylinder test is worth paying for."]'::jsonb, 2, 'The inverse question works because the margin is linear in the boost, so one evaluation fixes the whole sensitivity.'),
  ('perfsand', 'advanced', 'final', null, 26, 'The boost factor on a screening run is doubled away from its default. How does the reported margin respond?', '["It rises by a fixed amount, since the boost scales a strength that enters the expression only once.", "It doubles as well, in direct proportion with the multiplier.", "It moves unpredictably, because the boost also enters the critical flowing pressure through the far-field stress terms.", "It stays unchanged, since the boost is only reported back and never otherwise used."]'::jsonb, 0, 'That linearity is what makes a secant step enough to locate the zero, though a bisection is what the workflow runs.'),
  ('perfsand', 'advanced', 'final', null, 27, 'An asset team asks the sanding model for a produced sand rate in grams per cubic metre. What can you honestly give them?', '["A rate, once the governing row and the boost factor are fixed.", "A rate, provided the sweep is run at a fine enough step for every weak station along the interval to be represented.", "A time to first sand, which is the nearest quantity the criterion actually yields.", "Only an onset margin, since a rate needs failure, erosion and transport models nobody can calibrate here."]'::jsonb, 3, 'Onset is where the data stop supporting the model, a better place to draw a line than halfway into one.'),
  ('perfsand', 'advanced', 'final', null, 28, 'Every station in the sweep returns a negative margin before any drawdown is applied at all. What completion strategy does that point to?', '["Perforating selectively so as to avoid the weakest depth.", "Catching the failed material with sand control, since keeping the rock intact is no longer available.", "Reducing the drawdown until the margin turns positive, which is always possible because margin rises as drawdown falls.", "Raising the boost factor until the margin clears zero, and then producing normally."]'::jsonb, 1, 'A screen catches what has already failed, which is a valid strategy and a different one from preventing failure.'),
  ('perfsand', 'advanced', 'final', null, 29, 'The same interval ran correctly at a twenty five metre step and dropped its base at thirty metres. Why did the step size decide that?', '["Larger steps always drop rows, whatever the interval length.", "The interpolation of the stress and strength curves is exact only at station spacings that divide the survey grid evenly.", "A step dividing the interval lands the last whole step on the bottom, so any other step exits early.", "The clamp on the station depth fires only for steps below the survey increment."]'::jsonb, 2, 'Nothing in the output announced the early exit, which is what let the defect survive real use in the application.'),
  ('perfsand', 'advanced', 'final', null, 30, 'On the weakened profile a truncated sweep reported plus zero point six five megapascals where the true governing row is minus one point two five. Why is that error so serious?', '["The sign flips, so screening says drawdown is available on an interval whose base fails at any drawdown.", "The magnitude is nearly two megapascals, which is a large error.", "The governing row moves to the top of the interval, and a completion is always limited by its shallowest station.", "The reported depth is wrong by ten metres, which misplaces the perforating gun."]'::jsonb, 0, 'The base of a perforated interval is very often its weakest rock, so it is the worst place to lose a station.'),
  ('perfsand', 'advanced', 'final', null, 31, 'A reviewer sees a depth clamp and a break statement in the stepping loop and concludes the endpoint is handled. What did the reviewer miss?', '["The clamp used measured depth where true vertical was meant.", "The break statement fires one iteration too late, so the sweep adds an extra station past the bottom of the interval.", "The clamp had been applied to the computed margin rather than to the station depth.", "The while condition exits first, so neither line runs except when the step already divides the interval."]'::jsonb, 3, 'Both lines were written precisely for the ragged last step, and both were dead in every case that needed them.'),
  ('perfsand', 'advanced', 'final', null, 32, 'Faced with a golden that agreed perfectly, someone proposes tightening the comparison to more decimal places. Will that surface the missing station?', '["Yes, since the truncated rows differ slightly in interpolation.", "No, because the fixture divides evenly and both sweeps then produce identical rows at any precision.", "Yes, provided the tolerance is also tightened on the governing margin and not only on the individual station values.", "No, though simply adding more stations to the same fixture would have surfaced it."]'::jsonb, 1, 'A routine with a special case needs a fixture that instantiates it, and a dividing step was the only one on file.'),
  ('perfsand', 'advanced', 'final', null, 33, 'The oracle was written in a different language from the engine and still agreed with the defect. What does that episode say about independence?', '["It says the defect lies in the shared input data instead.", "It says the language choice was wrong, and an oracle in the engine''s own language would have diverged at the endpoint.", "Independence means deriving the answer differently, not typing the same control flow somewhere else.", "It says the oracle simply needs a tighter tolerance before it is able to disagree."]'::jsonb, 2, 'Building the visit list explicitly makes a mistake in one unlikely to be the same mistake in the other.'),
  ('perfsand', 'advanced', 'final', null, 34, 'Someone proposes interpolating true vertical depth linearly between survey stations to speed the sweep up. What is the objection?', '["Linear interpolation along an arc misses by decimetres, and a decimetre of vertical depth is real stress.", "None, since the stress curves are interpolated linearly too.", "It would move the governing row to the base of the interval, because errors in depth accumulate downwards along the well.", "It breaks the endpoint rule, since the deepest station would then overshoot the bottom."]'::jsonb, 0, 'Stress and strength curves are interpolated linearly in true vertical depth, so only the depth conversion is exempt.'),
  ('perfsand', 'advanced', 'final', null, 35, 'You are handed sweep output from a tool you did not write. Which single check is worth running before you read anything else?', '["Confirm the row count matches the interval over the step.", "Confirm the governing margin is the smallest value in the table, since a reduction over the rows can also be wrong.", "Confirm the shallowest row sits at the interval top, since that is where the loop begins.", "Confirm the deepest row sits at the interval bottom, whatever step size was typed into the tool."]'::jsonb, 3, 'The start is nearly always right because it is the initial value, so the end is where an off-by-one hides.'),
  ('perfsand', 'advanced', 'final', null, 36, 'A candidate reports a negative gauge margin on the capstone. Which self check has failed, and what does the failure mean?', '["The governing margin check, which requires a positive value.", "The gauge margin check, since the gauge is chosen strictly below the bound and cannot exceed it.", "None of these checks, because a negative gauge margin records a pack whose smallest grain is finer than any listed gauge.", "The bottom row check, because the bottom margin has to exceed the governing margin."]'::jsonb, 1, 'A negative value here almost always means the gravel row or the gauge step was taken from the wrong end.'),
  ('perfsand', 'advanced', 'final', null, 37, 'The capstone geometry is stated as open hole, but a candidate brings the overburden into the criterion anyway. What does that do to the sweep?', '["Only the governing row changes, since it takes the largest stress.", "Nothing changes, because the criterion takes the maximum and minimum of whichever three stresses are supplied to it.", "Every row changes, since the wrong pair substitutes the overburden for the minimum horizontal stress.", "The margins all shift by one constant, so the governing row itself is unaffected."]'::jsonb, 2, 'Three times the larger stress dominates the expression, so a swap of that size is not a small correction.'),
  ('perfsand', 'advanced', 'final', null, 38, 'On the capstone profile the margin rises with depth. Which row governs, and how does the bottom row stand in relation to it?', '["The top row governs and the bottom row is the loosest, so the bottom margin exceeds the governing one.", "The bottom row governs, since rock weakens towards the base.", "The two coincide, because the sweep runs to the interval bottom and an endpoint is by definition the limiting station.", "A middle row governs, because the profile turns over somewhere between the two ends."]'::jsonb, 0, 'Deeper is usually better because strength grows with compaction faster than pore pressure grows with depth.'),
  ('perfsand', 'advanced', 'final', null, 39, 'The governing margin comes out positive at the stated boost factor. What must therefore be true of the boost at which it reaches zero?', '["It must lie above the stated boost, by the same reasoning.", "It cannot be determined, because the relation between boost and margin depends on which row is governing at the time.", "It must equal the stated boost, because the bisection converges back on its own input.", "It has to lie below the stated boost factor, since raising the boost only raises the margin further."]'::jsonb, 3, 'That check catches a sign error in the strength term before any of the graded values are written down.'),
  ('perfsand', 'advanced', 'final', null, 40, 'The capstone step leaves a short last step rather than dividing the interval. What does that imply about the deepest row of the sweep?', '["It falls one whole step above the base of the perforations.", "It exists only because the sweep now runs to the bottom, and a truncated walk would never have computed it.", "It is duplicated, because the clamp writes the bottom station once from the loop and once more on the break.", "It carries the governing margin, since the last station is always the weakest one."]'::jsonb, 1, 'Both the interval and the step were chosen for the capstone precisely so that the ragged last step is exercised.'),
  ('perfsand', 'advanced', 'final', null, 41, 'Given that the margin is linear in the boost, why does the workflow bisect for the zero rather than take a single secant step?', '["A secant would land it in one step, and bisection is simply what the laboratory practice uses.", "Because the relation is only linear near the governing row.", "Because a secant step cannot be applied when the margin changes sign, and bisection is the only bracketing method here.", "Because bisection is the more accurate of the two on a function that is exactly linear."]'::jsonb, 0, 'Linearity also means the sensitivity can be read off directly rather than recomputed at each candidate value.'),
  ('perfsand', 'advanced', 'final', null, 42, 'Which academy course supplies the input that the last two modules rest on, and what would be missing without it?', '["Completion Design, which supplies the string above the packer.", "Stimulation Design, which supplies the fracture geometry that the frac pack option depends on for its conductivity.", "Geomechanics, which provides the stress and strength profile this course consumes but never derives.", "Well Integrity and P and A, which supplies the long term condition of a screen."]'::jsonb, 2, 'The sieve curve is the other input, and that one the course does derive, back in the Associate tier.');
